def transform(wb):
    ws = wb["Sheet1"]
    threshold = "2020-12-01"
    for col in range(ws.max_column, 8, -1):
        v = ws.cell(row=1, column=col).value
        if v is None:
            continue
        s = str(v)[:10]
        if s < threshold:
            ws.delete_cols(col, 1)
    return None
